/**
 * @module Generators/PoliticalIntelligenceDescriptions
 * @description Curated per-file descriptions for the political-intelligence
 * index page. Replaces the fragile first-paragraph extraction from Markdown
 * source files (which leaked document-owner metadata and `---` separators
 * into the rendered UI) with hand-written, high-quality descriptions keyed
 * by the repository-relative file path.
 *
 * Each entry ships with:
 * - a **canonical English description** (`description`) used as the fallback
 *   only when the caller requests English (`lang === 'en'`);
 * - an optional **per-language overlay** (`i18n`) mapping a subset of the 14
 *   supported language codes to a localized rendering of the same meaning.
 *
 * Non-English callers never receive the raw English `description` as a
 * fallback — {@link getCuratedDescription} synthesizes a localized sentence
 * from the localized title and the localized "kind" word (methodology,
 * template, reference, …) so every card on a non-English page reads
 * naturally in that language.
 *
 * Unmapped files fall back to a generic localized phrase built from the
 * file's display title — see {@link buildGenericFallback}.
 */

import type { LanguageCode } from '../types/index.js';

/** Per-language text overlay keyed by 2-letter language code. */
export type TextI18n = Partial<Record<LanguageCode, string>>;

/**
 * Back-compat alias for {@link TextI18n}. Preserved so downstream
 * TypeScript consumers that import this name from
 * `euparliamentmonitor/generators/political-intelligence-descriptions`
 * keep compiling. Prefer `TextI18n` for new code.
 */
export type DescriptionI18n = TextI18n;

/** One curated entry for a methodology / template / reference file. */
export interface CuratedDescription {
  /** Canonical English title shown on the card heading and used as the
   *  fallback when a language-specific title is not provided.
   *
   *  Leave empty to keep the H1-extracted title from the source Markdown
   *  file (useful for files whose H1 already reads well as a card title). */
  readonly title?: string;
  /** Optional per-language title overrides. English fallback (or the curated
   *  `title` field) is used for missing keys. */
  readonly titleI18n?: TextI18n;
