  UPDATE_DISMISS_LABELS,
  getLocalizedString,
  getTextDirection,
} from '../../constants/languages.js';
import { escapeHTML } from '../../utils/file-utils.js';
import { detectCategory } from '../../utils/article-category.js';
import {
  ARTICLE_TYPE_LABELS,
